// OPERATION COUNTING STEP BY STEP

// Example 1: single loop
function sumArray(arr) {                    // n = arr.length
    let total = 0;                          // 1 op
    for (let i = 0; i < arr.length; i++) { // n iterations
        total += arr[i];                    //   2 ops: array read + addition
    }
    return total;                           // 1 op
}
// Raw count: 1 + 2n + 1 = 2n + 2
// Dominant term: n  →  Big O: O(n)

// Example 2: nested loops, BOTH scale with n
function allPairs(arr) {
    for (let i = 0; i < arr.length; i++) {           // n iterations
        for (let j = i + 1; j < arr.length; j++) {   // ~n iterations
            console.log(arr[i], arr[j]);              //   1 op
        }
    }
}
// Raw count: approximately n²/2
// Dominant term: n²  →  Big O: O(n²)

// Example 3: inner loop is FIXED — most common counting mistake
function fixedInner(arr) {
    for (let i = 0; i < arr.length; i++) {  // n iterations
        for (let j = 0; j < 5; j++) {        // ALWAYS exactly 5 — not n
            console.log(arr[i], j);
        }
    }
}
// Raw count: 5n
// Dominant term: n  →  Big O: O(n)  NOT O(n²)
// The inner loop runs a CONSTANT number of times.
// It does not depend on n. So the function is still linear.

