class DynamicArray {
  constructor() {
    this.capacity = 1;
    this.size = 0;
    this.data = new Array(this.capacity);
    this.resizeCount = 0;
    this.totalCopyOperations = 0;
  }
  push(value) {
    if (this.size === this.capacity) {
      const newCapacity = this.capacity * 2;
      const newData = new Array(newCapacity);
      for (let i = 0; i < this.size; i++) {
        newData[i] = this.data[i];
        this.totalCopyOperations++;
      }
      this.data = newData;
      this.capacity = newCapacity;
      this.resizeCount++;
    }
    this.data[this.size] = value;
    this.size++;
  }
  get(index) {
    return this.data[index];
  }
}

function verifyAmortizedConstant(n) {
  const d = new DynamicArray();
  for (let i = 0; i < n; i++) d.push(i);
  return d.totalCopyOperations / n;
}

