// STEP 1: CLARIFY
// Q: Is comparison case-sensitive? -> Assume yes (case-sensitive)
// Q: Can the input contain empty strings? -> Yes, handle gracefully
// Q: Can strs be empty? -> Assume non-empty array of strings

// STEP 2: EXAMPLES
// ['eat','tea','tan','ate','nat','bat'] -> [['eat','tea','ate'],['tan','nat'],['bat']]
// [''] -> [['']]
// ['a'] -> [['a']]

function groupAnagramsBrute(strs) {
  const groups = [];
  const used = new Array(strs.length).fill(false);
  function isAnagram(a, b) {
    return a.split('').sort().join('') === b.split('').sort().join('');
  }
  for (let i = 0; i < strs.length; i++) {
    if (used[i]) continue;
    const group = [strs[i]];
    used[i] = true;
    for (let j = i + 1; j < strs.length; j++) {
      if (!used[j] && isAnagram(strs[i], strs[j])) {
        group.push(strs[j]);
        used[j] = true;
      }
    }
    groups.push(group);
  }
  return groups;
}

function groupAnagramsOptimal(strs) {
  const map = new Map();
  for (const s of strs) {
    const key = s.split('').sort().join('');
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(s);
  }
  return Array.from(map.values());
}

